import React, { CSSProperties, useMemo, useState } from 'react';
import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import usePageQuery from '../../core/hooks/usePageQuery';
import { useGetAllSupplierManageQuery, useGetUserQuery } from '../posApi';
import useSupplierListColumn from './useSupplierListColumn';
import { ISupplierDetails, ISupplierDetailsData } from '../../core/Interface/supplier.interface';

const useSupplierList = (
  handlePayment: (data: ISupplierDetailsData) => void,
  handleEdit: (data: ISupplierDetailsData) => void,
  handleDelete: (data: ISupplierDetailsData) => void
) => {
  const { page } = usePageQuery();
  const [popUpSupplierId, setPopUpSupplierId] = useState<string>('');
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const {
    data: supplierListData,
    isLoading,
    isFetching,
    error: fetchError,
  } = useGetAllSupplierManageQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText,
  });

  const supplierListMemo = useMemo(() => {
    return supplierListData?.data as ISupplierDetails;
  }, [supplierListData?.data]);

  const { data: companyData } = useGetUserQuery();

  const isImageEnabled = useMemo(() => {
    type WithImage = { company?: { isImageEnabled?: boolean } };
    const raw = companyData?.data as WithImage | undefined;
    return raw?.company?.isImageEnabled ?? false;
  }, [companyData]);

  const columns = useSupplierListColumn({
    handlePayment,
    handleEdit,
    handleDelete,
  });

  const table = useReactTable({
    data: fetchError ? [] : (supplierListMemo?.records ?? []),
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    meta: {
      getRowStyles: (row: Row<ISupplierDetailsData>): CSSProperties => ({}),
    },
    pageCount: supplierListMemo?.totalRecords ?? 0,
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error: fetchError,
    totalCount: supplierListMemo?.totalRecords ?? 0,
    popUpSupplierId,
    searchText,
    setSearchText,
    setPopUpSupplierId,
    isImageEnabled,
  };
};

export default useSupplierList;
